1	import { createServerClient } from "@supabase/ssr";
2	import { NextResponse, type NextRequest } from "next/server";
3	import type { Database } from "./types";
4	
5	const SUPABASE_URL = process.env.NEXT_PUBLIC_SUPABASE_URL;
6	const SUPABASE_ANON_KEY = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;
7	
8	if (!SUPABASE_URL || !SUPABASE_ANON_KEY) {
9	  throw new Error(
10	    "Missing Supabase environment variables. Set NEXT_PUBLIC_SUPABASE_URL and NEXT_PUBLIC_SUPABASE_ANON_KEY in .env.local",
11	  );
12	}
13	
14	export async function updateSession(request: NextRequest) {
15	  const supabaseResponse = { current: NextResponse.next({ request }) };
16	
17	  // Fast path: if the request carries no Supabase auth cookies at all,
18	  // there's no session to refresh. Skip the getUser() network call
19	  // entirely and return a null user. This saves ~100-200ms on every
20	  // anonymous request hitting public routes (/, /auth, /changelog,
21	  // /sitemap.xml, etc.).
22	  const hasAuthCookie = request.cookies
23	    .getAll()
24	    .some((c) => c.name.startsWith("sb-"));
25	  if (!hasAuthCookie) {
26	    return { supabaseResponse: supabaseResponse.current, user: null };
27	  }
28	
29	  const supabase = createServerClient<Database>(
30	    SUPABASE_URL!,
31	    SUPABASE_ANON_KEY!,
32	    {
33	      cookies: {
34	        getAll() {
35	          return request.cookies.getAll();
36	        },
37	        setAll(cookiesToSet) {
38	          cookiesToSet.forEach(({ name, value }) =>
39	            request.cookies.set(name, value),
40	          );
41	          supabaseResponse.current = NextResponse.next({ request });
42	          cookiesToSet.forEach(({ name, value, options }) =>
43	            supabaseResponse.current.cookies.set(name, value, options),
44	          );
45	        },
46	      },
47	    },
48	  );
49	
50	  // CRITICAL: call getUser() (not getSession()) — this refreshes the auth
51	  // token. Skipping or using getSession() will break auth cookies.
52	  const {
53	    data: { user },
54	  } = await supabase.auth.getUser();
55	
56	  return { supabaseResponse: supabaseResponse.current, user };
57	}
