1	"use client";
2	
3	import { useState, useEffect, createContext, useContext, useRef } from "react";
4	import { supabase } from "@/integrations/supabase/browser";
5	import type { User, Session } from "@supabase/supabase-js";
6	
7	type Profile = {
8	  credits: number;
9	  subscription_credits: number;
10	  topup_credits: number;
11	  bonus_credits: number;
12	  inbox_email: string | null;
13	  plan: string;
14	  email_enabled: boolean;
15	  auto_rank_enabled: boolean;
16	  subscription_ends_at: string | null;
17	};
18	
19	interface AuthContextType {
20	  user: User | null;
21	  session: Session | null;
22	  loading: boolean;
23	  isAdmin: boolean;
24	  profile: Profile | null;
25	  /**
26	   * Non-null when either the profile or role fetch failed. Consumers
27	   * can surface a toast/banner; the rest of the app still renders.
28	   */
29	  authError: string | null;
30	  signOut: () => Promise<void>;
31	  refreshProfile: () => Promise<void>;
32	}
33	
34	const AuthContext = createContext<AuthContextType>({
35	  user: null,
36	  session: null,
37	  loading: true,
38	  isAdmin: false,
39	  profile: null,
40	  authError: null,
41	  signOut: async () => {},
42	  refreshProfile: async () => {},
43	});
44	
45	// eslint-disable-next-line react-refresh/only-export-components
46	export const useAuth = () => useContext(AuthContext);
47	
48	export function AuthProvider({
49	  children,
50	  initialUser,
51	}: {
52	  children: React.ReactNode;
53	  initialUser?: User | null;
54	}) {
55	  // If the server pre-fetched a user, hydrate with it so the initial
56	  // client render matches the server HTML — no logged-out → logged-in
57	  // flash. loading starts false only when we already have a user.
58	  const [user, setUser] = useState<User | null>(initialUser ?? null);
59	  const [session, setSession] = useState<Session | null>(null);
60	  const [loading, setLoading] = useState(!initialUser);
61	  const [isAdmin, setIsAdmin] = useState(false);
62	  const [profile, setProfile] = useState<Profile | null>(null);
63	  const [authError, setAuthError] = useState<string | null>(null);
64	  const userIdRef = useRef<string | null>(initialUser?.id ?? null);
65	
66	  const fetchProfile = async (userId: string) => {
67	    try {
68	      const { data, error } = await supabase
69	        .from("profiles")
70	        .select(
71	          "credits, subscription_credits, topup_credits, bonus_credits, inbox_email, plan, email_enabled, auto_rank_enabled, subscription_ends_at",
72	        )
73	        .eq("user_id", userId)
74	        .single();
75	      if (error) throw error;
76	      if (data) {
77	        setProfile(data as Profile);
78	        setAuthError(null);
79	      }
80	    } catch (err) {
81	      console.error("[useAuth] Error fetching profile:", err);
82	      setAuthError(
83	        err instanceof Error
84	          ? `Could not load profile: ${err.message}`
85	          : "Could not load profile",
86	      );
87	    }
88	  };
89	
90	  const fetchRole = async (userId: string) => {
91	    try {
92	      const { data, error } = await supabase
93	        .from("user_roles")
94	        .select("role")
95	        .eq("user_id", userId);
96	      if (error) throw error;
97	      setIsAdmin(
98	        (data ?? []).some((r: { role: string }) => r.role === "admin"),
99	      );
100	    } catch (err) {
101	      console.error("[useAuth] Error fetching role:", err);
102	      // Role fetch failures should NOT silently leave isAdmin=false from
103	      // a previous session — reset it and surface the error so the admin
104	      // panel redirect doesn't look like a bug to the user.
105	      setIsAdmin(false);
106	      setAuthError(
107	        err instanceof Error
108	          ? `Could not verify permissions: ${err.message}`
109	          : "Could not verify permissions",
110	      );
111	    }
112	  };
113	
114	  const refreshProfile = async () => {
115	    if (userIdRef.current) await fetchProfile(userIdRef.current);
116	  };
117	
118	  useEffect(() => {
119	    const {
120	      data: { subscription },
121	    } = supabase.auth.onAuthStateChange(async (_event, nextSession) => {
122	      setSession(nextSession);
123	      setUser(nextSession?.user ?? null);
124	      userIdRef.current = nextSession?.user?.id ?? null;
125	
126	      if (nextSession?.user) {
127	        // setTimeout avoids the Supabase deadlock inside onAuthStateChange
128	        setTimeout(async () => {
129	          await Promise.all([
130	            fetchProfile(nextSession.user.id),
131	            fetchRole(nextSession.user.id),
132	          ]);
133	        }, 0);
134	      } else {
135	        setProfile(null);
136	        setIsAdmin(false);
137	        setAuthError(null);
138	      }
139	      setLoading(false);
140	    });
141	
142	    // Initial session fetch — reconciles server-provided initialUser
143	    // with the real Supabase session and loads profile/role.
144	    supabase.auth.getSession().then(async ({ data: { session: initial } }) => {
145	      setSession(initial);
146	      setUser(initial?.user ?? null);
147	      userIdRef.current = initial?.user?.id ?? null;
148	      if (initial?.user) {
149	        await Promise.all([
150	          fetchProfile(initial.user.id),
151	          fetchRole(initial.user.id),
152	        ]);
153	      }
154	      setLoading(false);
155	    });
156	
157	    return () => subscription.unsubscribe();
158	  }, []);
159	
160	  // Refresh profile on window focus + every 2min to keep credits current
161	  useEffect(() => {
162	    if (!user) return;
163	    const handleFocus = () => fetchProfile(user.id);
164	    window.addEventListener("focus", handleFocus);
165	    const interval = setInterval(() => fetchProfile(user.id), 120_000);
166	    return () => {
167	      window.removeEventListener("focus", handleFocus);
168	      clearInterval(interval);
169	    };
170	    // Intentional: re-run only on user identity change (id), not on every
171	    // Supabase user object reference change. fetchProfile is stable because
172	    // it closes over `supabase` which is a module singleton.
173	    // eslint-disable-next-line react-hooks/exhaustive-deps
174	  }, [user?.id]);
175	
176	  const signOut = async () => {
177	    await supabase.auth.signOut();
178	    setUser(null);
179	    setSession(null);
180	    setProfile(null);
181	    setIsAdmin(false);
182	    setAuthError(null);
183	  };
184	
185	  return (
186	    <AuthContext.Provider
187	      value={{
188	        user,
189	        session,
190	        loading,
191	        isAdmin,
192	        profile,
193	        authError,
194	        signOut,
195	        refreshProfile,
196	      }}
197	    >
198	      {children}
199	    </AuthContext.Provider>
200	  );
201	}
