3	const dsn = process.env.NEXT_PUBLIC_SENTRY_DSN;
4	const environment = process.env.NODE_ENV;
5	
6	export async function register() {
7	  if (!dsn) return;
8	
9	  if (process.env.NEXT_RUNTIME === "nodejs") {
10	    Sentry.init({
11	      dsn,
12	      environment,
13	      tracesSampleRate: environment === "production" ? 0.1 : 1.0,
14	      // Filter out noisy errors and PII
15	      beforeSend(event) {
16	        // Drop obvious health-check or favicon 404s
17	        if (event.request?.url?.match(/\/(favicon|robots|sitemap)/)) {
18	          return null;
19	        }
20	        return event;
21	      },
22	    });
23	  }
24	
